BATCHES = {
 "B24": ["YM-069","YM-070","YY-006","YY-010","YY-011","YY-012","YY-013","YY-014","YY-015","YY-016","YY-017","YY-018","YY-019","YY-020","YY-021","YY-022","YY-023","YY-024","YY2-001","YY2-002"],
 "B25": ["YY2-003","YY2-004","YY2-005","ZY-001","ZY-002","ZY-003","ZY-004"],
}

def main():
    batch = sys.argv[1]
    os.makedirs(OUT, exist_ok=True)
    written = []
    for cid in BATCHES[batch]:
        c = CASES[cid]
        obj = {"case_id": cid, "prediction_text": c["pred"], "basis": c["basis"],
               "confidence": c["conf"], "trigger": c["trig"]}
        p = os.path.join(OUT, cid + ".json")
        with open(p, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=1)
        written.append(p)
    # verify exactly this batch
    for cid in BATCHES[batch]:
        p = os.path.join(OUT, cid + ".json")
        with open(p, encoding="utf-8") as f:
            o = json.load(f)
        assert set(o.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
        assert o["case_id"] == cid
        assert set(o["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}, cid
        assert all(isinstance(o["trigger"][k], bool) for k in ("changed_main","reserve_used","disputed")), cid
        assert isinstance(o["trigger"]["reason"], str) and isinstance(o["confidence"], (int,float)), cid
        print(cid, os.path.getsize(p))
    print("OK", batch, len(BATCHES[batch]))

if __name__ == "__main__":
    main()
